const BASE = (import.meta.env.BASE_URL || '/').replace(/\/$/, '') + '/';
if (BASE !== '/') {
  ALL_PRODUCTS.forEach((p) => {
    p.photos.forEach((ph) => {
      if (ph.url && ph.url.startsWith('/')) {
        ph.url = BASE + ph.url.slice(1);
      }
    });
  });
}
